#!/usr/bin/env node
// @ts-check
/**
 * Renders `results/HISTORY.md`, the human-readable record of both indices over time, from
 * `results/history.json`: the AI-Friendliness Index (E01–E10) and, for the runs that carry it, the
 * Enterprise Readiness Index (R01–R06). Regenerated by every full `npm run evals` and by
 * `npm run evals:report`; a test asserts the committed file is fresh.
 *
 *   node evals/ai-friendliness/tools/report.mjs
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

import { insideDir } from '../lib/paths.mjs';

export const HISTORY_FILE = 'results/HISTORY.md';

/**
 * @typedef {{ label: string, date: string, sha?: string, scores: Record<string, number>, index: number, enterprise?: { scores: Record<string, number>, index: number } }} HistoryEntry
 * @typedef {{ id: string, name: string, movable: boolean, cls?: string }} EvalMeta
 * @typedef {{ label: string, date: string, sha?: string, scores: Record<string, number>, index: number }} SuiteRun
 */

/** @param {number} d */
const signed = (d) => (d > 0 ? `+${d.toFixed(1)}` : d.toFixed(1));
/** @param {string} s */
const bold = (s) => `**${s}**`;
/** @param {number} d */
const strongIfMoved = (d) => (d === 0 ? signed(d) : bold(signed(d)));
/** @param {number} a @param {number} b */
const delta = (a, b) => Math.round((a - b) * 10) / 10;
/** @param {EvalMeta} e */
const classOf = (e) => e.cls ?? (e.movable ? 'movable' : 'structural');
const STILL_NOTE = {
	structural: ' — structural; moves only with a documented breaking change',
	roadmap: ' — roadmap; moves with new components or features',
};

/**
 * The three sections (index over time, per-eval scores, what moved) for one suite.
 * @param {SuiteRun[]} runs sorted by date, all carrying this suite
 * @param {EvalMeta[]} evals
 * @param {string} h heading marker for the sections, e.g. `###`
 * @returns {string[]}
 */
function suiteSections(runs, evals, h) {
	const first = runs[0];
	const last = runs[runs.length - 1];
	const lines = [
		`${h} Index over time`,
		'',
		`| Run | Date | Commit | ${evals.map((e) => e.id).join(' | ')} | Index | Δ previous | Δ baseline |`,
		`| --- | --- | --- | ${evals.map(() => '---:').join(' | ')} | ---: | ---: | ---: |`,
	];
	runs.forEach((run, i) => {
		const prev = i === 0 ? null : runs[i - 1];
		const scores = evals.map((e) => (run.scores[e.id] ?? 0).toFixed(1)).join(' | ');
		const vsPrev = prev ? signed(delta(run.index, prev.index)) : '—';
		const vsBase = prev ? signed(delta(run.index, first.index)) : '—';
		lines.push(
			`| ${run.label} | ${run.date.slice(0, 10)} | \`${run.sha ?? 'unknown'}\` | ${scores} | **${run.index.toFixed(1)}** | ${vsPrev} | ${vsBase} |`
		);
	});

	lines.push(
		'',
		`${h} Per-eval scores`,
		'',
		`| ID | Eval | Class | ${runs.map((r) => r.label).join(' | ')} | Δ total |`,
		`| --- | --- | :---: | ${runs.map(() => '---:').join(' | ')} | ---: |`
	);
	/** @type {{ id: string, name: string, cls: string, moved: number }[]} */
	const movement = [];
	for (const e of evals) {
		const moved = delta(last.scores[e.id] ?? 0, first.scores[e.id] ?? 0);
		movement.push({ id: e.id, name: e.name, cls: classOf(e), moved });
		const cells = runs.map((r) => (r.scores[e.id] ?? 0).toFixed(1)).join(' | ');
		lines.push(`| ${e.id} | ${e.name} | ${classOf(e)} | ${cells} | ${strongIfMoved(moved)} |`);
	}
	const indexCells = runs.map((r) => bold(r.index.toFixed(1))).join(' | ');
	lines.push(`| — | **Index** | | ${indexCells} | **${signed(delta(last.index, first.index))}** |`);

	const movers = movement.filter((m) => m.moved !== 0).sort((a, b) => b.moved - a.moved);
	const still = movement.filter((m) => m.moved === 0);
	lines.push(
		'',
		`${h} What moved`,
		'',
		`From \`${first.label}\` (${first.index.toFixed(1)}) to \`${last.label}\` (${last.index.toFixed(1)}): ${signed(delta(last.index, first.index))} points over ${runs.length} runs.`,
		''
	);
	if (movers.length) {
		lines.push('Biggest movers:', '');
		for (const m of movers) lines.push(`- ${m.id} ${m.name} ${signed(m.moved)}`);
		lines.push('');
	}
	if (still.length) {
		lines.push('Unchanged across all runs:', '');
		for (const m of still) {
			const note = STILL_NOTE[/** @type {keyof typeof STILL_NOTE} */ (m.cls)] ?? '';
			lines.push(`- ${m.id} ${m.name} (${(last.scores[m.id] ?? 0).toFixed(1)})${note}`);
		}
		lines.push('');
	}
	return lines;
}

/**
 * @param {HistoryEntry[]} history
 * @param {EvalMeta[]} evals the AI-friendliness evals
 * @param {EvalMeta[]} [enterpriseEvals] the enterprise-readiness evals; their section renders when a run carries the suite
 * @returns {string} Markdown
 */
export function renderHistory(history, evals, enterpriseEvals = []) {
	const runs = [...history].sort((a, b) => a.date.localeCompare(b.date));
	const enterpriseRuns = runs
		.filter((r) => r.enterprise)
		.map((r) => ({
			label: r.label,
			date: r.date,
			sha: r.sha,
			scores: r.enterprise?.scores ?? {},
			index: r.enterprise?.index ?? 0,
		}));
	const lines = [
		'# Eval indices — history',
		'',
		'Generated by `npm run evals:report` from `results/history.json` — do not edit by hand.',
		'Each row is one full run (`npm run evals --label <name>`); each index is the unweighted mean of its evals.',
		'',
		'## AI-Friendliness Index',
		'',
		'The ten evals E01–E10: how legible the library is to coding agents.',
		'',
		...suiteSections(runs, evals, '###'),
	];
	if (enterpriseRuns.length && enterpriseEvals.length) {
		lines.push(
			'## Enterprise Readiness Index',
			'',
			`The six evals R01–R06: how far the token theme and the patterns meet the enterprise UI requirements. Measured from \`${enterpriseRuns[0].label}\` on; earlier runs have no value.`,
			'',
			...suiteSections(enterpriseRuns, enterpriseEvals, '###')
		);
	}
	lines.push(
		'Per-run details (raw measurements, per-component scores, unmeasured pairs) live in `results/<label>.json`.',
		''
	);
	return lines.join('\n');
}

/**
 * Write `results/HISTORY.md` for a suite directory.
 * @param {string} suiteDir
 * @param {HistoryEntry[]} history
 * @param {EvalMeta[]} evals
 * @param {EvalMeta[]} [enterpriseEvals]
 */
export function writeHistoryReport(suiteDir, history, evals, enterpriseEvals = []) {
	const file = insideDir(suiteDir, HISTORY_FILE);
	fs.writeFileSync(file, renderHistory(history, evals, enterpriseEvals));
	return file;
}

async function main() {
	const suiteDir = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
	const { metrics } = await import('../metrics/index.mjs');
	const { metrics: enterprise } = await import('../../enterprise/metrics/index.mjs');
	const history = JSON.parse(fs.readFileSync(insideDir(suiteDir, 'results', 'history.json'), 'utf8'));
	const file = writeHistoryReport(suiteDir, history, metrics, enterprise);
	process.stdout.write(`wrote ${path.relative(process.cwd(), file)}\n`);
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) await main();
